widget.solution:
def trade_pnl(shares, entry, exit):
    # profit or loss on one trade, in pounds
    return shares * (exit - entry)


def test_profit():
    # 40 shares bought at £12.50 and sold at £13.75
    pnl = trade_pnl(40, 12.50, 13.75)
    assert pnl == 50.0


def test_loss():
    # 40 shares bought at £12.50 and sold at £11.25
    pnl = trade_pnl(40, 12.50, 11.25)
    assert pnl == -50.0
